// Package apidoc renders the API reference of a Go module (docsync api): one
// Markdown file per public package under docs/api/, from the source and its
// doc comments, like go doc. DS-GEN regenerates it and reports a difference.
package apidoc

import (
	"bytes"
	"fmt"
	"go/ast"
	"go/build"
	"go/doc"
	"go/doc/comment"
	"go/parser"
	"go/printer"
	"go/token"
	"os"
	"path"
	"path/filepath"
	"sort"
	"strings"
)

// Dir is where the reference lives, relative to the module.
const Dir = "docs/api"

// Marker is the first line of every generated file. A file under Dir with
// the marker belongs to docsync api: it is rewritten or removed by it.
const Marker = "<!-- Code generated by docsync api. DO NOT EDIT. -->"

// Package is a public package to document.
type Package struct {
	Rel        string // directory relative to the module, "." for the root
	ImportPath string
}

// Generate returns the files of the reference: path relative to the module
// mapped to content. modPath is the module path.
func Generate(dir, modPath string, pkgs []Package) (map[string]string, error) {
	out := map[string]string{}
	type entry struct{ file, importPath, synopsis string }
	var index []entry
	sort.Slice(pkgs, func(i, j int) bool { return pkgs[i].ImportPath < pkgs[j].ImportPath })
	for _, p := range pkgs {
		md, synopsis, ok, err := render(filepath.Join(dir, filepath.FromSlash(p.Rel)), p.ImportPath)
		if err != nil {
			return nil, err
		}
		if !ok {
			continue
		}
		name := FileName(modPath, p.Rel)
		out[path.Join(Dir, name)] = md
		index = append(index, entry{name, p.ImportPath, synopsis})
	}
	if len(index) == 0 {
		return out, nil
	}
	var b strings.Builder
	b.WriteString(Marker + "\n\n# API reference\n\n")
	fmt.Fprintf(&b, "Generated from the source of `%s` with `docsync api`; the doc comments are the documentation. The guides around it explain how the pieces fit.\n\n", modPath)
	b.WriteString("| Package | Synopsis |\n|---|---|\n")
	for _, e := range index {
		fmt.Fprintf(&b, "| [%s](%s) | %s |\n", e.importPath, e.file, strings.ReplaceAll(e.synopsis, "|", `\|`))
	}
	out[path.Join(Dir, "README.md")] = b.String()
	return out, nil
}

// FileName is the reference file of the package in rel.
func FileName(modPath, rel string) string {
	if rel == "." {
		return path.Base(modPath) + ".md"
	}
	return strings.ReplaceAll(rel, "/", "-") + ".md"
}

// IsGenerated reports whether content was written by docsync api.
func IsGenerated(content string) bool { return strings.HasPrefix(content, Marker) }

func render(dir, importPath string) (md, synopsis string, ok bool, err error) {
	fset := token.NewFileSet()
	entries, err := os.ReadDir(dir)
	if err != nil {
		return "", "", false, err
	}
	// Files per platform, in platform order: a declaration of a name keeps
	// the first platform's file, so the reference has one per name and the
	// platform-only API (Windows syscalls, npcap) too.
	var files []*ast.File
	declared := map[string]bool{}
	taken := map[string]bool{}
	for _, ctx := range buildContexts {
		for _, e := range entries {
			n := e.Name()
			if taken[n] || e.IsDir() || !strings.HasSuffix(n, ".go") || strings.HasSuffix(n, "_test.go") {
				continue
			}
			if match, err := ctx.MatchFile(dir, n); err != nil || !match {
				continue
			}
			taken[n] = true
			f, err := parser.ParseFile(fset, filepath.Join(dir, n), nil, parser.ParseComments)
			if err != nil || ast.IsGenerated(f) || ignored(f) || f.Name.Name == "main" {
				continue
			}
			files = append(files, dropDeclared(f, declared))
		}
		for _, f := range files {
			for _, k := range declNames(f) {
				declared[k] = true
			}
		}
	}
	if len(files) == 0 {
		return "", "", false, nil
	}
	p, err := doc.NewFromFiles(fset, files, importPath, doc.PreserveAST)
	if err != nil {
		return "", "", false, err
	}
	if len(p.Consts)+len(p.Vars)+len(p.Funcs)+len(p.Types) == 0 {
		return "", "", false, nil
	}
	g := &gen{fset: fset, pkg: p, files: files}
	return g.markdown(), p.Synopsis(p.Doc), true, nil
}

// buildContexts are the platforms the reference describes, in order.
var buildContexts = func() []build.Context {
	var out []build.Context
	for _, goos := range []string{"linux", "darwin", "windows", "freebsd"} {
		c := build.Default
		c.GOOS, c.GOARCH, c.CgoEnabled = goos, "amd64", false
		c.BuildTags, c.ToolTags = nil, nil
		out = append(out, c)
	}
	return out
}()

// declNames are the keys of a file's top-level declarations: "T", "f",
// "T.m" for a method.
func declNames(f *ast.File) []string {
	var out []string
	for _, d := range f.Decls {
		switch d := d.(type) {
		case *ast.FuncDecl:
			out = append(out, funcKey(d))
		case *ast.GenDecl:
			for _, s := range d.Specs {
				switch s := s.(type) {
				case *ast.TypeSpec:
					out = append(out, s.Name.Name)
				case *ast.ValueSpec:
					for _, n := range s.Names {
						out = append(out, n.Name)
					}
				}
			}
		}
	}
	return out
}

func funcKey(d *ast.FuncDecl) string {
	if d.Recv == nil || len(d.Recv.List) == 0 {
		return d.Name.Name
	}
	t := d.Recv.List[0].Type
	if s, ok := t.(*ast.StarExpr); ok {
		t = s.X
	}
	switch x := t.(type) {
	case *ast.IndexExpr:
		t = x.X
	case *ast.IndexListExpr:
		t = x.X
	}
	if id, ok := t.(*ast.Ident); ok {
		return id.Name + "." + d.Name.Name
	}
	return d.Name.Name
}

// dropDeclared removes the declarations of names an earlier platform's file
// declared.
func dropDeclared(f *ast.File, declared map[string]bool) *ast.File {
	if len(declared) == 0 {
		return f
	}
	var keep []ast.Decl
	for _, d := range f.Decls {
		switch d := d.(type) {
		case *ast.FuncDecl:
			if declared[funcKey(d)] {
				continue
			}
		case *ast.GenDecl:
			var specs []ast.Spec
			for _, s := range d.Specs {
				switch s := s.(type) {
				case *ast.TypeSpec:
					if declared[s.Name.Name] {
						continue
					}
				case *ast.ValueSpec:
					dup := false
					for _, n := range s.Names {
						dup = dup || declared[n.Name]
					}
					if dup {
						continue
					}
				}
				specs = append(specs, s)
			}
			if len(specs) == 0 && d.Tok != token.IMPORT {
				continue
			}
			c := *d
			c.Specs = specs
			d = &c
			keep = append(keep, d)
			continue
		}
		keep = append(keep, d)
	}
	c := *f
	c.Decls = keep
	return &c
}

// ignored reports a file excluded from every build ("//go:build ignore").
func ignored(f *ast.File) bool {
	for _, cg := range f.Comments {
		if cg.Pos() >= f.Package {
			break
		}
		for _, c := range cg.List {
			if t := strings.TrimSpace(strings.TrimPrefix(c.Text, "//go:build")); t != c.Text && t == "ignore" {
				return true
			}
		}
	}
	return false
}

type gen struct {
	fset  *token.FileSet
	pkg   *doc.Package
	files []*ast.File
	b     strings.Builder
	seen  map[string]bool
}

func (g *gen) markdown() string {
	p := g.pkg
	g.seen = map[string]bool{}
	fmt.Fprintf(&g.b, "%s\n\n# package %s\n\n```go\nimport %q\n```\n\n", Marker, p.Name, p.ImportPath)
	g.text(p.Doc)
	if len(p.Consts) > 0 {
		g.b.WriteString("## Constants\n\n")
		g.values(p.Consts)
	}
	if len(p.Vars) > 0 {
		g.b.WriteString("## Variables\n\n")
		g.values(p.Vars)
	}
	if len(p.Funcs) > 0 {
		g.b.WriteString("## Functions\n\n")
		for _, f := range p.Funcs {
			g.fn("###", f)
		}
	}
	if len(p.Types) > 0 {
		g.b.WriteString("## Types\n\n")
		for _, t := range p.Types {
			fmt.Fprintf(&g.b, "### type %s\n\n", t.Name)
			g.code(withoutDoc(t.Decl))
			g.text(t.Doc)
			g.values(t.Consts)
			g.values(t.Vars)
			for _, f := range t.Funcs {
				g.fn("####", f)
			}
			for _, f := range t.Methods {
				g.fn("####", f)
			}
		}
	}
	return strings.TrimRight(g.b.String(), "\n") + "\n"
}

func (g *gen) values(vs []*doc.Value) {
	for _, v := range vs {
		g.code(withoutDoc(v.Decl))
		g.text(v.Doc)
	}
}

// withoutDoc returns a copy of d without its doc comment, which the text
// after the code block prints; the printer would print it again.
func withoutDoc(d *ast.GenDecl) *ast.GenDecl {
	c := *d
	c.Doc = nil
	if !c.Lparen.IsValid() && len(c.Specs) == 1 {
		switch s := c.Specs[0].(type) {
		case *ast.ValueSpec:
			sc := *s
			sc.Doc = nil
			c.Specs = []ast.Spec{&sc}
		case *ast.TypeSpec:
			sc := *s
			sc.Doc = nil
			c.Specs = []ast.Spec{&sc}
		}
	}
	return &c
}

func (g *gen) fn(level string, f *doc.Func) {
	d := *f.Decl
	d.Body, d.Doc = nil, nil
	key := f.Recv + "." + f.Name
	if g.seen[key] {
		return // one declaration per build constraint: the first is enough
	}
	g.seen[key] = true
	if f.Recv != "" {
		fmt.Fprintf(&g.b, "%s func (%s) %s\n\n", level, strings.TrimPrefix(f.Recv, "*"), f.Name)
	} else {
		fmt.Fprintf(&g.b, "%s func %s\n\n", level, f.Name)
	}
	g.code(&d)
	g.text(f.Doc)
}

// code prints a declaration with the comments inside it (field comments),
// without its doc comment.
func (g *gen) code(n ast.Node) {
	var node any = n
	if f := g.file(n.Pos()); f != nil {
		var inner []*ast.CommentGroup
		for _, c := range f.Comments {
			if c.Pos() > n.Pos() && c.End() <= n.End() {
				inner = append(inner, c)
			}
		}
		node = &printer.CommentedNode{Node: n, Comments: inner}
	}
	var buf bytes.Buffer
	cfg := printer.Config{Mode: printer.UseSpaces | printer.TabIndent, Tabwidth: 4}
	if err := cfg.Fprint(&buf, g.fset, node); err != nil {
		fmt.Fprintf(&buf, "// %v", err)
	}
	fmt.Fprintf(&g.b, "```go\n%s\n```\n\n", strings.TrimRight(buf.String(), "\n"))
}

func (g *gen) file(pos token.Pos) *ast.File {
	for _, f := range g.files {
		if f.FileStart <= pos && pos <= f.FileEnd {
			return f
		}
	}
	return nil
}

// link resolves a doc link ([Name], [T.M], [pkg.Name]) to the heading of
// this file, or to pkg.go.dev for another package.
func (g *gen) link(l *comment.DocLink) string {
	if l.ImportPath != "" && l.ImportPath != g.pkg.ImportPath {
		u := "https://pkg.go.dev/" + l.ImportPath
		if l.Recv != "" {
			return u + "#" + l.Recv + "." + l.Name
		}
		if l.Name != "" {
			return u + "#" + l.Name
		}
		return u
	}
	if l.Recv != "" {
		return "#func-" + strings.ToLower(l.Recv) + "-" + strings.ToLower(l.Name)
	}
	for _, t := range g.pkg.Types {
		if t.Name == l.Name {
			return "#type-" + strings.ToLower(l.Name)
		}
		for _, f := range t.Funcs {
			if f.Name == l.Name {
				return "#func-" + strings.ToLower(l.Name)
			}
		}
	}
	for _, f := range g.pkg.Funcs {
		if f.Name == l.Name {
			return "#func-" + strings.ToLower(l.Name)
		}
	}
	return "" // a constant or variable: no heading of its own
}

func (g *gen) text(s string) {
	if strings.TrimSpace(s) == "" {
		return
	}
	pr := g.pkg.Printer()
	pr.HeadingLevel = 4
	pr.DocLinkBaseURL = "https://pkg.go.dev"
	pr.DocLinkURL = g.link
	g.b.Write(pr.Markdown(g.pkg.Parser().Parse(s)))
	g.b.WriteString("\n")
}
